def trump_detector(s):
    vowels = "aeiou"
    s = s.lower()
    total_vowels = 0
    extra_vowels = 0
    i = 0
    while i < len(s):
        if s[i] in vowels:
            total_vowels += 1
            count = 1
            while i + 1 < len(s) and s[i] == s[i + 1]:
                count += 1
                i += 1
            if count > 1:
                extra_vowels += count - 1
        i += 1
    return round(extra_vowels / total_vowels, 2)
